// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): English 10, Unit 1, Literary Analysis.
// Our own wording and questions, written to the named national standards the course follows: the Common Core State
// Standards for English Language Arts, Reading: Literature, grades 9-10 (RL.9-10.1 to 9-10.6 and 9-10.9). English 9 teaches
// these standards as close reading of single passages; English 10 goes deeper, so every skill here is a move in literary
// ANALYSIS: writing a claim with evidence and commentary across paragraphs (1), comparing two texts on a shared theme (2),
// how a complex character develops and advances a theme (3), how the cumulative impact of word choices shapes tone and
// meaning (4), how an author's choices about structure and time create tension and surprise (5), cultural experience in
// world literature (6), and how an author draws on and transforms a source (9). RL.9-10.7 (two mediums) is met in
// English 9, and RL.9-10.8 is marked "not applicable to literature" in the standards. Seven outline topics, one skill each.
// Every passage is either public domain (a few lines from a famous work, named with author, title and date, and checked
// against the lines as printed), a fact about a famous work stated plainly and hedged, or labelled "Fictional passage" and
// written for this unit; nothing is quoted from a copyrighted text, and none of English 9's passages is reused. A question
// asks about the words on the page: the answer is in the passage or is a standard term of the course. Every question offers
// lettered choices in its prompt and takes the letter (or the choice's own words); the right letter moves around.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Video pictures: figure coordinates use a 100 x 34 sketch, north/up. Flow arrows trace before labels appear. */
const sketch=(title,regions,notes=[])=>{const pts={},polys=[];regions.forEach(([label,xy,col=0],i)=>{const v=xy.map(([x,y],k)=>{const n=String.fromCharCode(65+k)+i;pts[n]=[x,y];return n;}).join('');polys.push({v,label,col});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const flow=(title,stages)=>{const q=sketch(title,stages.map(([label],i)=>[label,[[i*36,13],[i*36+28,13],[i*36+28,25],[i*36,25]],i]),stages.map(([,detail],i)=>[i*36+14,7,detail]));q.segs=[];for(let i=0;i<2;i++){q.pts['P'+i]=[i*36+29,19];q.pts['Q'+i]=[i*36+35,19];q.segs.push({v:`P${i}Q${i}`,arrows:1,col:i,w:2});}q.hide=Object.keys(q.pts).join('');return q;};
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const pass=(title,texts,small=true)=>({t:'passages',title,texts,...(small?{small:true}:{})});
const L='ABCDEF';
/* lettered choices, the right one moved to position k: returns {text, letter} */
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
const FIC='Fictional passage';
/* the passages: [source label, lines, whether the lines are verse (joined with a slash in a prompt)] */
